-- Сгенерировано tools/gen_ff_legacy.py из Fiend Folio Reheated — не править руками.
-- Старые глобальные имена Fiend Folio для кода совместимости других модов (IPECAC и др.):
-- задаются только если имя свободно и предмет с таким именем зарегистрирован (Reloaded включён).
-- Модовые предметы из content-repentogon регистрируются после загрузки Lua ранних модов, поэтому это
-- функция: main.lua зовёт её в MC_POST_MODS_LOADED и ещё раз в начале забега (раньше IPECAC).
LOCALFIXES = LOCALFIXES or {}
function LOCALFIXES.ApplyFFLegacy(silent)
local set, missing = 0, {}
local function legacy(tbl, tblName, key, value, src)
	if tbl == nil or tbl[key] ~= nil then return end
	if value ~= nil and value > 0 then
		tbl[key] = value
		set = set + 1
	else
		missing[#missing + 1] = tblName .. '.' .. key .. ' (' .. src .. ')'
	end
end
